window.__EBT=window.__EBT||{};window.__EBT["ro"]=window.__EBT["ro"]||{};window.__EBT["ro"]["Sir"]=[[1,[[1,"Toată înțelepciunea vine de la Domnul,"],[2,"Cine poate număra nisipul mărilor,"],[3,"Cine va cerceta înălțimea cerului,"],[4,"Înțelepciunea a fost creată înaintea tuturor lucrurilor,"],[6,"Cui i-a fost descoperită rădăcina înțelepciunii?"],[8,"Există un înțelept, foarte de temut,"],[9,"El a creat-o."],[10,"Ea este cu orice făptură după darul lui."],[11,"Frica de Domnul este slavă, bucurie,"],[12,"Frica de Domnul va încânta inima,"],[13,"Cine se teme de Domnul, îi va merge bine în cele din urmă."],[14,"A te teme de Domnul este începutul înțelepciunii."],[15,"Ea a pus o temelie veșnică cu oamenii."],[16,"A te teme de Domnul este plinătatea înțelepciunii."],[17,"Ea își va umple toată casa cu lucruri de dorit,"],[18,"Frica de Domnul este cununa înțelepciunii,"],[19,"A văzut-o și a măsurat-o."],[20,"A te teme de Domnul este rădăcina înțelepciunii."],[22,"Mânia nedreaptă nu poate fi niciodată justificată,"],[23,"Un om care are răbdare va rezista un sezon,"],[24,"Își va ascunde cuvintele până la momentul potrivit,"],[25,"O vorbă înțeleaptă este în comorile înțelepciunii;"],[26,"Dacă vrei înțelepciune, păzește poruncile"],[27,"căci frica de Domnul este înțelepciune și învățătură."],[28,"Nu te supune fricii de Domnul."],[29,"Nu fi ipocrit în ochii oamenilor."],[30,"Nu te înălța,"]]],[2,[[1,"Fiul meu, dacă vii să slujești Domnului,"],[2,"Îndreaptă-ți inima, îndura constant,"],[3,"Agăță-te de el și nu pleca,"],[4,"Acceptă orice ți se aduce,"],[5,"Căci aurul este încercat în foc,"],[6,"Pune-ți încrederea în el și el te va ajuta."],[7,"Voi toți cei ce vă temeți de Domnul, așteptați îndurarea Lui."],[8,"Voi toți cei ce vă temeți de Domnul, puneți-vă încrederea în El,"],[9,"Voi toți cei ce vă temeți de Domnul, nădăjduiți în lucruri bune,"],[10,"Privește generațiile de odinioară și vezi:"],[11,"Căci Domnul este plin de milă și milă."],[12,"Vai de inimile înfricoșate, de mâinile slabe,"],[13,"Vai de inima slabă! Căci nu crede."],[14,"Vai de voi care v-ați pierdut răbdarea!"],[15,"Cei care se tem de Domnul nu vor asculta de cuvintele Lui."],[16,"Cei care se tem de Domnul vor căuta plăcerea Lui."],[17,"Cei care se tem de Domnul își vor pregăti inimile,"],[18,"Vom cădea în mâinile Domnului,"]]],[3,[[1,"Ascultă-mă, tatăl tău, o, copiii mei,"],[2,"Căci Domnul cinstește pe tată peste copii,"],[3,"Cel care cinstește pe tatăl său va face ispășire pentru păcate."],[4,"Cel care dă slavă mamei sale este ca acela care adună comori."],[5,"Cine își cinstește tatăl se va bucura de copiii săi."],[6,"Cel ce dă slavă tatălui său va avea zile lungi."],[7,"și va sluji sub părinții lui, ca stăpâni."],[8,"Cinstește-ți tatăl în fapte și în cuvânt,"],[9,"Căci binecuvântarea tatălui întărește casele copiilor,"],[10,"Nu te slăvi pe tine însuți în dezonoarea tatălui tău,"],[11,"Căci slava omului este din cinstea tatălui său,"],[12,"Fiul meu, ajută-ți tatăl la bătrânețe,"],[13,"Dacă nu înțelege, ai răbdare cu el."],[14,"Căci bunătatea față de tatăl tău nu va fi uitată."],[15,"În ziua necazului tău se va aduce aminte de tine,"],[16,"Cel ce-și părăsește tatăl este ca un hulitor."],[17,"Fiul meu, continuă cu smerenia treburile tale;"],[18,"Cu cât ești mai mare, smerește-te cu atât mai mult,"],[20,"Căci puterea Domnului este mare,"],[21,"Nu căuta lucruri prea grele pentru tine,"],[22,"Gândește-te la lucrurile care ți s-au poruncit,"],[23,"Nu fi prea ocupat cu sarcini care te depășesc,"],[24,"Căci îngâmfarea multora i-a rătăcit."],[25,"Nu există lumină fără ochi."],[26,"O inimă încăpățânată o va face rău la sfârșit."],[27,"O inimă încăpățânată va fi împovărată de necazuri."],[28,"Nenorocirea celor mândri nu are vindecare,"],[29,"Inima prudentului va înțelege un proverb."],[30,"Apa va stinge un foc în flăcări;"],[31,"Cel care răsplătește rândurile bune are grijă de ceea ce va urma."]]],[4,[[1,"Fiul meu, nu-i priva pe sărac de existența lui."],[2,"Nu întrista un suflet flămând,"],[3,"Nu adăugați mai multe probleme unei inimi care este provocată."],[4,"Nu respinge un rugător în suferința lui."],[5,"Nu-ți întoarce ochii de la cel care întreabă."],[6,"Căci dacă te blestemă în amărăciunea sufletului său,"],[7,"Îndrăgește-te de adunare."],[8,"Înclină-ți urechea spre un sărac."],[9,"Izbăvește-l pe cel nedreptățit din mâna celui care îl nedreptățește;"],[10,"Fii ca un tată pentru orfan,"],[11,"Înțelepciunea îi înalță pe fiii ei,"],[12,"Cine o iubește, iubește viața."],[13,"Cel care o ține tare va moșteni slava."],[14,"Cei care slujesc slujitorul ei celui Sfânt."],[15,"Cel ce o ascultă va judeca neamurile."],[16,"Dacă are încredere în ea, o va moșteni,"],[17,"Căci la început ea va umbla cu el pe căi strâmbe,"],[18,"Apoi ea îl va întoarce din nou pe calea cea dreaptă,"],[19,"Dacă el se rătăcește, ea îl va părăsi,"],[20,"Privește oportunitatea și ferește-te de rău."],[21,"Căci este o rușine care aduce păcat,"],[22,"Nu da dovadă de parțialitate, discreditându-ți sufletul."],[23,"Nu vă abțineți să vorbiți când este pentru siguranță."],[24,"Căci înțelepciunea va fi cunoscută prin vorbire,"],[25,"Nu vorbi împotriva adevărului"],[26,"Nu-ți fie rușine să-ți mărturisești păcatele."],[27,"Nu te întinde ca să calce un prost."],[28,"Luptă până la moarte după adevăr,"],[29,"Nu te grăbi cu limba,"],[30,"Nu fi ca un leu în casa ta,"],[31,"Nu lăsa mâna ta întinsă pentru a primi,"]]],[5,[[1,"Nu-ți pune inima asupra bunurilor tale."],[2,"Nu-ți urma propria minte și puterea ta"],[3,"Nu spune: „Cine va avea stăpânire peste mine?”"],[4,"Nu spune: „Am păcătuit și ce mi s-a întâmplat?”"],[5,"Nu fi atât de încrezător în ispășire"],[6,"Nu spune: „Compasiunea Lui este mare."],[7,"Nu așteptați să vă întoarceți la Domnul."],[8,"Nu-ți pune inima pe câștiguri nedrepte,"],[9,"Nu vărsați cu fiecare vânt."],[10,"Fii statornic în înțelegerea ta."],[11,"Fii rapid să auzi"],[12,"Dacă ai pricepere, răspunde aproapelui tău;"],[13,"Gloria și dezonoarea sunt în discuție."],[14,"Nu fi numit șoptător."],[15,"Nu fi ignorant într-o chestiune mare sau mică."]]],[6,[[1,"Nu deveniți un dușman în loc de un prieten;"],[2,"Nu te înălța în sfatul sufletului tău,"],[3,"Îți vei mânca frunzele, vei distruge roadele tale,"],[4,"Un suflet rău îl va nimici pe cel care îl are,"],[5,"Cuvintele dulci vor înmulți prietenii unui bărbat."],[6,"Să fie mulți cei care sunt în pace cu tine,"],[7,"Dacă vrei să-ți câștigi un prieten, adu-l într-o perioadă de testare,"],[8,"Căci există un prieten doar pentru o ocazie."],[9,"Și există un prieten care se transformă într-un dușman."],[10,"Și există un prieten care este un însoțitor la masă,"],[11,"În prosperitatea ta, el va fi ca tine,"],[12,"Dacă ești doborât, el va fi împotriva ta,"],[13,"Separați-vă de dușmanii tăi,"],[14,"Un prieten fidel este o apărare puternică."],[15,"Nu există nimic care să poată fi luat în schimbul unui prieten fidel."],[16,"Un prieten fidel este un medicament care salvează vieți."],[17,"Cine se teme de Domnul își îndreaptă prietenia în mod corespunzător;"],[18,"Fiule, adună învăţătură din tinereţea ta."],[19,"Vino la ea ca unul care ară și seamănă"],[20,"Cât de aspră este ea cu cei neînvățați!"],[21,"Ea se va odihni asupra lui ca pe o piatră puternică a încercării."],[22,"Căci înțelepciunea este după numele ei."],[23,"Ascultă, fiule, și acceptă judecata mea."],[24,"Adu-ți picioarele în lanțurile ei,"],[25,"Pune-ți umărul sub ea și poartă-o."],[26,"Vino la ea cu tot sufletul tău."],[27,"Căutați și căutați și ea vi se va face cunoscută."],[28,"Căci în cele din urmă vei găsi odihna ei;"],[29,"Cadrele ei vor fi pentru tine ca un acoperământ de putere,"],[30,"Căci pe ea este o podoabă de aur,"],[31,"O vei îmbrăca ca o haină de slavă,"],[32,"Fiul meu, dacă vrei, vei fi instruit."],[33,"Dacă îți place să auzi, vei primi."],[34,"Stați în mulțimea bătrânilor."],[35,"Fiți dispus să ascultați fiecare discurs evlavios."],[36,"Dacă vezi un om înțelegător, ajunge la el devreme."],[37,"Lăsați mintea voastră să stea pe rânduielile Domnului"]]],[7,[[1,"Să nu faci rău,"],[2,"Pleacă de la greșit,"],[3,"Fiul meu, nu semăna pe brazdele nelegiuirii,"],[4,"Nu căuta preeminență de la Domnul,"],[5,"Nu te îndreptăți în prezența Domnului,"],[6,"Nu căuta să fii judecător,"],[7,"Nu păcătuiți împotriva mulțimii orașului."],[8,"Nu comite un păcat de două ori,"],[9,"Nu spune: „El se va uita la mulțimea darurilor mele."],[10,"Nu fi slăbit la inimă în rugăciunea ta."],[11,"Să nu râzi un om ca să-l batjocorească când este în amărăciunea sufletului său,"],[12,"Nu pune la cale o minciună împotriva fratelui tău,"],[13,"Refuză să rostești o minciună,"],[14,"Nu bolborosi în adunarea bătrânilor."],[15,"Nu urăști munca grea"],[16,"Nu te număra printre mulțimea păcătoșilor."],[17,"Smilește-ți sufletul mult,"],[18,"Nu schimba un prieten cu ceva,"],[19,"Nu te priva de o soție înțeleaptă și bună,"],[20,"Nu abuzați de un slujitor care lucrează cu credincioșie,"],[21,"Lasă-ți sufletul să iubească un slujitor înțelept."],[22,"Ai vite? Ai grijă de ei."],[23,"Aveţi copii? Corectează-le,"],[24,"Ai fete? Aveți grijă de trupurile lor,"],[25,"Dă-ți fiica în căsătorie și vei fi realizat o chestiune grozavă."],[26,"Ai o soție care îți place? Nu o alungați."],[27,"Onorează-ți tatăl din toată inima ta,"],[28,"Amintește-ți că te-ai născut din ei."],[29,"Teme-te de Domnul din tot sufletul tău;"],[30,"Cu toată puterea ta iubește pe cel care te-a făcut."],[31,"Teme-te de Domnul și cinstește preotul."],[32,"De asemenea, întinde mâna către bietul om,"],[33,"Un dar are har în ochii fiecărui om viu."],[34,"Nu-i evita pe cei care plâng,"],[35,"Nu întârzia să vizitezi un om bolnav,"],[36,"În toate cuvintele tale, amintește-ți eternitatea,"]]],[8,[[1,"Nu te certa cu un om puternic,"],[2,"Nu te lupta cu un om bogat, ca nu cumva el te va birui;"],[3,"Nu te certa cu un bărbat cu gura tare."],[4,"Nu-ți bate joc de un om nepoliticos,"],[5,"Nu reproșa unui om când se întoarce de la păcat."],[6,"Nu dezonora un om la bătrânețe,"],[7,"Nu te bucura de moartea nimănui."],[8,"Nu neglija discursul celor înțelepți."],[9,"Nu rata discursul bătrânilor,"],[10,"Nu aprinde cărbunii păcătosului,"],[11,"Nu te ridica din prezența unui om insolent,"],[12,"Nu împrumuta unui bărbat care este mai puternic decât tine;"],[13,"Nu fii sigur peste posibilitățile tale."],[14,"Nu mergeți la justiție cu un judecător;"],[15,"Nu călători cu un om nesăbuit,"],[16,"Nu lupta cu un om furios."],[17,"Nu te sfătui cu un prost,"],[18,"Nu face nimic secret în fața unui străin,"],[19,"Nu-ți deschide inima oricărui bărbat."]]],[9,[[1,"Nu fi gelos pe soția din sânul tău,"],[2,"Nu-ți da sufletul unei femei"],[3,"Nu merge să întâlnești o femeie care joacă prostituată,"],[4,"Nu te asocia cu o femeie care este cântăreață,"],[5,"Nu te uita la o fecioară,"],[6,"Nu-ți da sufletul prostituatelor,"],[7,"Nu te uita în jur pe străzile orașului."],[8,"Întoarce-ți ochii de la o femeie frumoasă,"],[9,"Nu cina deloc cu o femeie care are un soț,"],[10,"Nu părăsi un vechi prieten;"],[11,"Nu invidia succesul unui păcătos;"],[12,"Nu vă bucurați de plăcerile celor nelegiuiți."],[13,"Ține-te departe de omul care are puterea de a ucide,"],[14,"Pe cât de bine poți, încearcă să-ți cunoști vecinii,"],[15,"Lăsați conversația voastră să fie cu oameni pricepuți."],[16,"Lasă oamenii drepți să fie însoțitori la masa ta."],[17,"O lucrare este lăudată datorită priceperii artizanului;"],[18,"Un bărbat cu gura tare este periculos în orașul său."]]],[10,[[1,"Un judecător înțelept își va instrui poporul."],[2,"Așa cum este judecătorul poporului său, așa sunt și funcționarii lui."],[3,"Un rege nedisciplinat își va distruge poporul."],[4,"Guvernarea pământului este în mâna Domnului."],[5,"prosperitatea unui om este în mâna Domnului."],[6,"Nu fi supărat pe aproapele tău pentru fiecare greșeală."],[7,"Mândria este urâtă înaintea Domnului și a oamenilor."],[8,"Suveranitatea este transferată de la națiune la națiune"],[9,"De ce sunt mândre murdăria și cenușa?"],[10,"O boala lunga isi bate joc de medic."],[11,"Căci când un om este mort,"],[12,"Este începutul mândriei când un om se îndepărtează de Domnul."],[13,"Căci începutul mândriei este păcatul."],[14,"Domnul a doborât tronurile conducătorilor"],[15,"Domnul a smuls rădăcinile neamurilor"],[16,"Domnul a răsturnat pământurile popoarelor"],[17,"El a luat pe unii dintre ei și i-a nimicit,"],[18,"Mândria nu a fost creată pentru bărbați,"],[19,"Al cui urmași are cinste?"],[20,"În mijlocul rudelor, cel care le conduce are cinste."],[22,"Omul bogat, cel onorabil și cel sărac"],[23,"Nu este corect să dezonorezi un sărac care are pricepere."],[24,"Prințul, judecătorul și omul puternic vor fi onorați."],[25,"Oamenii liberi vor sluji unui slujitor înțelept."],[26,"Nu vă etalați înțelepciunea în a vă face munca."],[27,"Mai bine este cel ce muncește și se înmulțește în toate lucrurile,"],[28,"Fiul meu, slăvește sufletul tău în smerenie,"],[29,"Cine îl va îndreptăţi pe cel care păcătuieşte împotriva propriului suflet?"],[30,"Un om sărac este onorat pentru cunoștințele sale."],[31,"Dar cine este cinstit în sărăcie, cu cât mai mult în bogății?"]]],[11,[[1,"Înțelepciunea celor smeriți îi va ridica capul,"],[2,"Nu lăudați un bărbat pentru aspectul său frumos."],[3,"Albina este mică printre creaturile zburătoare,"],[4,"Nu te lauda cu hainele pe care le porti,"],[5,"Mulți regi s-au așezat pe pământ,"],[6,"Mulți oameni puternici au fost foarte disproporți."],[7,"Nu da vina înainte de a investiga."],[8,"Nu răspunde înainte de a auzi."],[9,"Nu vă certați despre o chestiune care nu vă privește."],[10,"Fiul meu, nu fi ocupat cu multe chestiuni;"],[11,"Este unul care trudește, trudește și se grăbește,"],[12,"Există unul care este lent și are nevoie de ajutor,"],[13,"și și-a ridicat capul"],[14,"Lucruri bune și rele, viață și moarte,"],[17,"Darul Domnului rămâne la cei evlavioși."],[18,"Cineva se îmbogățește prin sârguința și abnegația sa,"],[19,"când spune: „Am găsit odihnă,"],[20,"Fii statornic în legământul tău și fă-l,"],[21,"Nu te mira de faptele unui păcătos,"],[22,"Binecuvântarea Domnului este în răsplata celor evlavioși."],[23,"Nu spune: „La ce mă folosește?"],[24,"Nu spune: „Am destul."],[25,"În ziua lucrurilor bune, lucrurile rele sunt uitate."],[26,"Căci este un lucru ușor înaintea Domnului"],[27,"Necazul unui ceas face ca desfătările să fie uitate."],[28,"Nu-i spune pe nimeni fericit înainte de moartea lui."],[29,"Nu aduce pe toți oamenii în casa ta,"],[30,"Ca o potârnichie momeală într-o cușcă, așa este inima unui om mândru."],[31,"Căci el stă la pândă pentru a transforma lucrurile bune în rele,"],[32,"Dintr-o scânteie de foc se aprinde un morman de cărbuni,"],[33,"Ai grijă de un făcător de rău, căci el plănuiește lucruri rele,"],[34,"Primește un străin în casa ta și el îți va distrage atenția cu argumente"]]],[12,[[1,"Dacă faci bine, știi cui îi faci,"],[2,"Fă bine unui om evlavios și vei găsi o răsplată -"],[3,"Niciun bine nu va veni celui ce continuă să facă răul,"],[4,"Dă omului evlavios,"],[5,"Fă bine cuiva care este smerit."],[6,"Căci și Cel Preaînalt urăște pe păcătoși,"],[7,"Dă-i omului bun,"],[8,"Prietenul unui bărbat nu va fi încercat pe deplin în prosperitate."],[9,"În prosperitatea unui om, dușmanii lui sunt întristați."],[10,"Să nu ai încredere niciodată în dușmanul tău,"],[11,"Deși se smerește și merge plecat,"],[12,"Nu-l pune lângă tine,"],[13,"Cine va fi milă de un fermecător care este muşcat de un şarpe,"],[14,"Chiar și așa, cine va fi milă de cel ce se duce la un păcătos,"],[15,"O vreme va sta cu tine,"],[16,"Vrăjmașul va vorbi dulce cu buzele lui,"],[17,"Dacă adversitatea te întâlnește, îl vei găsi acolo înaintea ta."],[18,"El va clătina din cap, va bate din palme,"]]],[13,[[1,"Cel ce atinge smoala va fi spurcat."],[2,"Nu prelua o povară mai presus de puterea ta."],[3,"Bogatul greșește și amenință."],[4,"Dacă ești profitabil, el te va exploata."],[5,"Dacă ai ceva, el va locui cu tine."],[6,"Are nevoie de tine? Atunci te va înșela,"],[7,"Te va face de rușine prin delicatesele lui"],[8,"Ai grijă să nu fii înșelat"],[9,"Dacă te invită un om puternic, fii rezervat,"],[10,"Nu-l apăsa, ca să nu fii împins înapoi."],[11,"Nu încerca să vorbești cu el ca un egal,"],[12,"Cel care nu păstrează secrete pentru sine este lipsit de milă."],[13,"Păstrează-le pentru tine și ai grijă,"],[15,"Fiecare făptură vie își iubește propriul soi,"],[16,"Toată carnea se asociază cu propriul lor soi."],[17,"Ce părtășie ar avea lupul cu mielul?"],[18,"Ce pace este între o hienă și un câine?"],[19,"Măgarii sălbatici sunt prada leilor în pustie;"],[20,"Smerenia este o urâciune pentru un om mândru;"],[21,"Când un om bogat este zdruncinat, el este sprijinit de prietenii săi,"],[22,"Când un bogat cade, sunt mulți ajutoare."],[23,"Un om bogat vorbește și toți păstrează tăcerea."],[24,"Bogățiile sunt bune dacă nu au păcat."],[25,"Inima omului își schimbă chipul,"],[26,"O înfățișare veselă este un semn al unei inimi prospere."]]],[14,[[1,"Ferice de omul care nu a alunecat cu gura,"],[2,"Ferice de cel al cărui suflet nu-l condamnă,"],[3,"Bogățiile nu sunt potrivite pentru o persoană zgârcită."],[4,"Cel care adună tăgăduindu-se pe sine adună pentru alții."],[5,"Dacă cineva este rău cu el însuși, cu cine va fi bun?"],[6,"Nu există nimeni mai rău decât cel care se împotrivește cu el însuși."],[7,"Chiar dacă face bine, o face în uitare."],[8,"Un avar este rău."],[9,"Ochiul unui om lacom nu este mulțumit de partea lui."],[10,"Un zgârcitor bate rău pâinea,"],[11,"Fiul meu, după ce ai, trată-te bine,"],[12,"Amintește-ți că moartea nu va aștepta,"],[13,"Fă bine prietenilor tăi înainte de a muri."],[14,"Nu te priva de o zi bună."],[15,"Nu vei lăsa munca ta altuia,"],[16,"Dă, ia și tratează-te bine,"],[17,"Orice carne îmbătrânește ca o haină,"],[18,"Ca frunzele care înfloresc pe un copac gros,"],[19,"Fiecare lucrare putrezește și cade,"],[20,"Ferice de omul care meditează la înțelepciune,"],[21,"Cel care are în vedere căile ei în inima lui"],[22,"Du-te după ea ca un vânător,"],[23,"El care se uită la ferestrele ei"],[24,"El care se cazează aproape de casa ei"],[25,"Își va ridica cortul aproape de ea,"],[26,"El își va pune copiii sub adăpostul ei,"],[27,"De ea va fi acoperit de căldură,"]]],[15,[[1,"Cel ce se teme de Domnul va face aceasta."],[2,"Îl va întâlni ca pe o mamă,"],[3,"Ea îl va hrăni cu pâine a înțelegerii"],[4,"El va rămâne peste ea și nu va fi mișcat."],[5,"Ea îl va înălța mai presus de vecinii săi."],[6,"El va moșteni bucuria, o cunună de bucurie,"],[7,"Oamenii proști nu o vor obține."],[8,"Ea este departe de mândrie."],[9,"Lauda nu este atrăgătoare în gura unui păcătos;"],[10,"Căci lauda se va rosti cu înțelepciune;"],[11,"Nu spune: „Prin Domnul m-am depărtat”;"],[12,"Nu spune: „El este cel care m-a făcut să greșesc”;"],[13,"Domnul urăște orice urâciune;"],[14,"El însuși a făcut om de la început"],[15,"Dacă alegi, poți păzi poruncile."],[16,"El a pus foc și apă înaintea ta."],[17,"Înaintea omului este viața și moartea."],[18,"Căci înțelepciunea Domnului este mare."],[19,"Ochii Lui sunt asupra celor care se tem de El."],[20,"El nu a poruncit nimănui să fie nelegiuit."]]],[16,[[1,"Nu-ți dori o mulțime de copii neprofitabili,"],[2,"Dacă se înmulțesc, nu vă bucurați de ele"],[3,"Nu ai încredere în viața lor."],[4,"Căci de la cel ce are pricepere, o cetate va fi populată,"],[5,"Am văzut multe astfel de lucruri cu ochii mei."],[6,"Într-o adunare de păcătoși, un foc va fi aprins."],[7,"El nu a fost liniștit față de uriașii din vremuri,"],[8,"Nu i-a cruțat pe vecinii lui Lot,"],[9,"Nu i-a fost milă de oamenii pierzării"],[10,"sau la fel, cei șase sute de mii de lachei"],[11,"Chiar dacă există o persoană cu gâtul înțepenit,"],[12,"După cum mare este mila Lui, tot așa este și îndreptarea Lui."],[13,"Păcătosul nu va scăpa cu prada."],[14,"El va face loc pentru fiecare lucrare de îndurare."],[17,"Nu spune: „Voi fi ascuns de Domnul”"],[18,"Iată, cerul, cerul cerurilor,"],[19,"Munții și temeliile pământului împreună"],[20,"Nicio inimă nu se va gândi la aceste lucruri."],[21,"Ca o furtună pe care nimeni nu o poate vedea,"],[22,"Cine va vesti faptele lui de dreptate?"],[23,"Cel care este lipsit de înțelegere se gândește la aceste lucruri."],[24,"Fiul meu, ascultă-mă, învață cunoștințe,"],[25,"Voi da instrucțiuni cu precizie,"],[26,"În judecata Domnului sunt lucrările Lui de la început."],[27,"Și-a aranjat lucrările pentru totdeauna,"],[28,"Nimeni nu-și împinge vecinul deoparte."],[29,"După aceasta și Domnul s-a uitat la pământ"],[30,"Toate felurile de vietuitoare i-au acoperit suprafața,"]]],[17,[[1,"Domnul a creat omenirea din pământ,"],[2,"Le-a dat zile după număr și un timp stabilit,"],[3,"El i-a înzestrat cu puterea lor,"],[4,"El a pus frica de om peste orice făptură,"],[6,"Le-a dat sfat, limbă, ochi,"],[7,"El i-a umplut cu cunoașterea înțelepciunii,"],[8,"Și-a pus ochii pe inimile lor,"],[10,"Și vor lăuda numele Lui sfânt,"],[11,"El le-a adăugat cunoștințe,"],[12,"El a făcut un legământ veșnic cu ei,"],[13,"Ochii lor au văzut măreția gloriei Lui."],[14,"El le-a zis: „Păziți-vă de orice nelegiuire”."],[15,"Căile lor sunt mereu înaintea lui."],[17,"Pentru fiecare națiune a pus un conducător,"],[19,"Toate lucrările lor sunt la fel de clare ca soarele dinaintea lui."],[20,"Nelegiuirile lor nu sunt ascunse de el."],[22,"Cu el pomana unui om este ca un sigiliu."],[23,"Apoi se va ridica și le va răsplăti,"],[24,"Cu toate acestea, celor care se pocăiesc el acordă o întoarcere."],[25,"Întoarce-te la Domnul și părăsește păcatele."],[26,"Întoarce-te din nou la Cel Preaînalt și întoarce-te de la nelegiuire."],[27,"Cine va lăuda pe Cel Preaînalt în Iad,"],[28,"Ziua Recunoștinței piere din morți, ca de la cel care nu există."],[29,"Cât de mare este mila Domnului,"],[30,"Căci oamenii nu sunt capabili de orice,"],[31,"Ce este mai strălucitor decât soarele? Cu toate acestea, chiar și aceasta poate fi eclipsată."],[32,"El se uită la puterea înălțimii cerului,"]]],[18,[[1,"Cel care trăiește pentru totdeauna a creat întregul univers."],[2,"Doar Domnul este drept."],[4,"El nu a dat putere să-și declare nimănui lucrările sale."],[5,"Cine ar putea măsura puterea măreției sale?"],[6,"Cât despre faptele minunate ale Domnului, nu se poate lua de la ele sau adăuga la ele,"],[7,"Când un om a terminat, atunci el este doar la început."],[8,"Ce este omenirea și ce scop servește ea?"],[9,"Numărul de zile ale omului este de cel mult o sută de ani."],[10,"Ca o picătură de apă din mare și o pietricică din nisip,"],[11,"Din această cauză Domnul a avut răbdare cu ei,"],[12,"El a văzut și a văzut sfârșitul lor, că este rău."],[13,"Mila omului este asupra aproapelui său;"],[14,"El are milă de cei care acceptă pedepsirea,"],[15,"Fiul meu, nu adăuga ocară faptelor tale bune,"],[16,"Roua nu ameliorează căldura arzătoare?"],[17,"Iată, nu este un cuvânt mai bun decât un dar?"],[18,"Un prost este lipsit de grație și abuziv."],[19,"Învață înainte de a vorbi."],[20,"Înainte de judecată, examinează-te,"],[21,"Smeriți-vă înainte să vă îmbolnăviți."],[22,"Nu lăsați nimic să vă împiedice să vă plătiți jurământul la timp."],[23,"Înainte de a face un jurământ, pregătește-te."],[24,"Gândește-te la mânia care va veni în zilele sfârșitului,"],[25,"În zilele de plinătate amintește-ți de vremea foametei."],[26,"De dimineața până seara, ora se schimbă."],[27,"Un om înțelept este precaut în toate."],[28,"Fiecare om priceput cunoaște înțelepciunea."],[29,"Cei care erau pricepuți în cuvinte au devenit și ei înțelepți,"],[30,"Nu merge după poftele tale."],[31,"Dacă oferi sufletului tău pe deplin bucuria dorinței ei,"],[32,"Nu vă veseli cu mult lux,"],[33,"Nu fi făcut cerșetor prin banchete cu bani împrumutați"]]],[19,[[1,"Un muncitor care este bețiv nu va deveni bogat."],[2,"Vinul și femeile îi vor face pe bărbați pricepuți să se rătăcească."],[3,"Degradarea și viermii îl vor avea ca moștenire."],[4,"Cel care se grăbește să se încreadă are o inimă superficială."],[5,"Cel ce se bucură de răutate va fi osândit."],[6,"Cine urăște bârfele are mai puțină răutate."],[7,"Nu repeta niciodată ceea ce ți se spune,"],[8,"Fie că este vorba despre prieten sau dușman, nu spune."],[9,"Căci dacă te-a auzit și te-a păzit,"],[10,"Ai auzit ceva? Lasă-l să moară cu tine."],[11,"Un nebun va naștere în durere cu un cuvânt,"],[12,"Ca o săgeată care se lipește în carnea coapsei,"],[13,"Întrebați un prieten; s-ar putea să nu fi făcut-o."],[14,"Întrebați-vă aproapele; poate că nu a spus-o."],[15,"Întrebați un prieten; de multe ori există calomnie."],[16,"Există unul care alunecă, și nu din inimă."],[17,"mustrează-ți aproapele înainte de a-l amenința;"],[20,"Toată înțelepciunea este frica de Domnul."],[22,"Cunoașterea răutății nu este înțelepciune."],[23,"Există o răutate și este o urâciune."],[24,"Mai bine este cel care are puțină înțelegere și se teme de Dumnezeu,"],[25,"Există o subtilitate rafinată și este nedreaptă."],[26,"Este unul care face rău, care-și atârnă capul cu jale;"],[27,"înclinându-și fața și prefăcându-se surd la o ureche."],[28,"Și dacă din lipsă de putere este împiedicat să păcătuiască,"],[29,"Un bărbat va fi cunoscut după înfățișarea sa."],[30,"Ținuta unui bărbat, râs rânjit,"]]],[20,[[1,"Există o mustrare care nu este oportună;"],[2,"Cât de bine este să mustrești, decât să fii supărat."],[4,"Cum este pofta unui eunuc de a desflori o fecioară,"],[5,"Este unul care tace și este găsit înțelept;"],[6,"Este unul care tace, căci nu are de dat un răspuns;"],[7,"Un om înțelept va tăcea până când îi va veni vremea,"],[8,"Cel care folosește multe cuvinte va fi urât."],[9,"Există o prosperitate pe care o găsește un om în nenorociri;"],[10,"Există un dar care nu vă va folosi;"],[11,"Sunt pierderi din cauza gloriei;"],[12,"Există unul care cumpără mult pentru puțin,"],[13,"Cel ce este înțelept în cuvinte se va face iubit;"],[14,"Darul unui nebun nu vă va folosi,"],[15,"Va da puțin și va insulta mult."],[16,"Nebunul va spune: „Nu am niciun prieten,"],[17,"Cât de des, și de câte, se va râde de el!"],[18,"O alunecare pe trotuar este mai bună decât o alunecare cu limba."],[19,"Un om fără har este o poveste în afara sezonului."],[20,"O pildă din gura unui nebun va fi respinsă;"],[21,"Există unul care este împiedicat să păcătuiască din cauza lipsei."],[22,"Există unul care își distruge sufletul prin sfială."],[23,"Există unul care, din sfială, face promisiuni prietenului său;"],[24,"O minciună este o pată urâtă asupra unei persoane."],[25,"Un hoț este mai bun decât un om care minte continuu,"],[26,"Destinația unui mincinos este dezonoarea."],[27,"Cel ce este înțelept în cuvinte se va înainta."],[28,"Cel ce-și lucrează pământul își va înălța recolta."],[29,"Favorurile și darurile orbesc ochii celor înțelepți,"],[30,"Înțelepciunea care este ascunsă și comoara care nu se vede -"],[31,"Mai bine este un om care își ascunde nebunia"]]],[21,[[1,"Fiul meu, ai păcătuit?"],[2,"Fugi de păcat ca de fața unui șarpe;"],[3,"Toată nelegiuirea este ca o sabie cu două tăișuri."],[4,"Teroarea și violența vor irosi bogățiile."],[5,"Rugăciunea din gura unui sărac ajunge până la urechile lui Dumnezeu,"],[6,"Cine urăște mustrarea este pe calea păcătosului."],[7,"Cel ce este puternic în limbă este cunoscut de departe;"],[8,"Cel care își construiește casa cu banii altor oameni"],[9,"Adunarea oamenilor răi este ca un mănunchi de câlți"],[10,"Calea păcătoșilor este pavat cu pietre;"],[11,"Cel care ține legea devine stăpân pe intenția ei."],[12,"Cine nu este deștept nu va fi instruit."],[13,"Cunoașterea unui om înțelept va fi făcută din belșug ca potop,"],[14,"Părțile interioare ale unui prost sunt ca un vas spart."],[15,"Dacă un om priceput aude un cuvânt înțelept,"],[16,"Vorbăria unui prost este ca o povară în cale,"],[17,"Vorbirea omului prudent va fi căutată în adunare."],[18,"Ca o casă distrusă, așa este înțelepciunea unui nebun."],[19,"Învățătura este ca niște lanțuri pe picioarele unui neînțelept,"],[20,"Un prost își ridică vocea râzând,"],[21,"Învățătura este pentru om priceput ca o podoabă de aur,"],[22,"Piciorul unui prost se repezi într-o casă,"],[23,"Un om nebun se uită la ușa unei case,"],[24,"Este nepoliticos ca cineva să asculte la o uşă,"],[25,"Buzele străinilor vor fi întristate de aceste lucruri,"],[26,"Inima proștilor este în gura lor,"],[27,"Când cel nelegiuit blestemă un potrivnic,"],[28,"Un șoptător își spurcă propriul suflet,"]]],[22,[[1,"Un om leneș este comparat cu o piatră care este pângărită."],[2,"Un om leneș este comparat cu mizeria unui bălegar."],[3,"Un copil nedisciplinat este o rușine pentru tatăl său,"],[4,"O fiică prudentă va moșteni un soț al ei."],[5,"Cea care este arogantă aduce rușine tatălui și soțului."],[6,"Conversația prost timp este ca muzica în doliu,"],[7,"Cel care învață pe nebun este ca cel care lipește cioburi de oală,"],[8,"Cel care învață pe un nebun este ca cel care învață pe un om care doarme."],[11,"Plângi pentru mort, căci îi lipsește lumina."],[12,"Doliu pentru morți durează șapte zile,"],[13,"Nu vorbi mult cu un om prost,"],[14,"Ce ar fi mai greu decât plumbul?"],[15,"Nisipul, sarea și o masă de fier sunt mai ușor de suportat"],[16,"Lemnul încins și legat într-o clădire nu va fi eliberat prin scuturare."],[17,"O inimă stabilită pe o înțelegere gânditoare"],[18,"Gardurile așezate pe un loc înalt nu vor rezista împotriva vântului;"],[19,"Cine ciulge ochiul va face să cadă lacrimi."],[20,"Cine aruncă o piatră în păsări le sperie."],[21,"Dacă ai scos sabia împotriva unui prieten, nu dispera,"],[22,"Dacă ai deschis gura împotriva unui prieten, nu te teme,"],[23,"Câștigă încredere în aproapele tău în sărăcia lui,"],[24,"Înaintea focului sunt vaporii și fumul unui cuptor,"],[25,"Nu îmi va fi rușine să adăpostesc un prieten."],[26,"Dacă mi se întâmplă vreun rău din cauza lui,"],[27,"Cine va pune veghe asupra gurii mele,"]]],[23,[[1,"Doamne, Tată și Stăpân al vieții mele,"],[2,"Cine va pune flagel peste gândul meu,"],[3,"În caz contrar, erorile mele s-ar putea multiplica,"],[4,"Doamne, Tată și Dumnezeul vieții mele,"],[5,"și abate de la mine dorința rea."],[6,"Să nu mă apuce nici lăcomia, nici pofta."],[7,"Ascultați, copiii mei, disciplina gurii."],[8,"Păcătosul va fi biruit prin buzele lui."],[9,"Nu-ți obișnui gura cu un jurământ,"],[10,"căci, ca un slujitor care este biciuit continuu, nu va duce lipsă de vânătăi,"],[11,"Un om cu multe jurăminte va fi plin de nelegiuire."],[12,"Există un mod de vorbire care este îmbrăcat cu moarte."],[13,"Nu-ți obișnui gura cu grosolănia,"],[14,"Adu-ți aminte de tatăl tău și de mama ta,"],[15,"Un bărbat obișnuit cu limbajul abuziv"],[16,"Două feluri de oameni înmulțesc păcatele,"],[17,"Toată pâinea este dulce pentru un desfrânat."],[18,"Un bărbat care se rătăcește din propriul său pat conjugal"],[19,"Ochii oamenilor sunt teroarea lui."],[20,"Toate lucrurile i-au fost cunoscute înainte de a fi create,"],[21,"Acest om va fi pedepsit pe străzile orașului."],[22,"La fel este și o soție care își părăsește soțul,"],[23,"Căci mai întâi, ea a fost neascultătoare de legea Celui Prea Înalt."],[24,"Ea va fi scoasă în adunare."],[25,"Copiii ei nu vor prinde rădăcini."],[26,"Își va lăsa memoria pentru un blestem."],[27,"Și cei lăsați în urmă vor ști că nu este nimic mai bun decât frica de Domnul,"]]],[24,[[1,"Înțelepciunea își va lăuda propriul suflet,"],[2,"Ea își va deschide gura în adunarea Celui Prea Înalt,"],[3,"„Am ieşit din gura Celui Prea Înalt,"],[4,"Am trăit în locuri înalte,"],[5,"Singur am înconjurat circuitul cerului,"],[6,"În valurile mării și pe tot pământul,"],[7,"Cu toate acestea am căutat odihna."],[8,"Atunci Creatorul tuturor lucrurilor mi-a dat o poruncă."],[9,"El m-a creat de la început, înainte de veacuri."],[10,"În cortul sfânt, am slujit înaintea lui."],[11,"În cetatea iubită, la fel mi-a dat odihnă."],[12,"Am prins rădăcini într-un popor care a fost onorat,"],[13,"Am fost înălțat ca un cedru în Liban,"],[14,"Am fost înălțat ca un palmier pe malul mării,"],[15,"Ca și scorțișoară și aspalathus, am dat un parfum parfumurilor."],[16,"Ca terebintul, mi-am întins crengile."],[17,"Asemenea viței de vie, am dat har."],[19,"„Veniți la mine, toți cei care Mă doriți,"],[20,"Căci memoria mea este mai dulce decât mierea,"],[21,"Cei care mă mănâncă vor fi foame de mai mult."],[22,"Cel ce mă ascultă nu se va rușina."],[23,"Toate aceste lucruri sunt cartea legământului Dumnezeului Prea Înalt,"],[25,"El este cel care abundă înțelepciunea, ca Pișon,"],[26,"El face priceperea plină ca Eufratul,"],[27,"care face ca învăţătura să strălucească ca lumina,"],[28,"Primul bărbat nu a cunoscut-o perfect."],[29,"Căci gândurile ei sunt pline din mare,"],[30,"Am ieșit ca un pârâu de canal dintr-un râu,"],[31,"Am spus: „Îmi voi uda grădina,"],[32,"Voi scoate încă la lumină învățătură ca dimineața,"],[33,"Voi continua să vărs învățătură ca o profeție,"],[34,"Vezi că nu am muncit numai pentru mine,"]]],[25,[[1,"Mă bucur de trei lucruri,"],[2,"Dar sufletul meu urăște trei feluri de oameni,"],[3,"Dacă nu ai adunat nimic în tinerețe,"],[4,"Cât de frumos este judecata la cei cu părul cărunt,"],[5,"Cât de frumoasă este înțelepciunea bătrânilor,"],[6,"Multă experiență este coroana bătrânilor."],[7,"Sunt nouă lucruri la care m-am gândit și în inima mea le-am socotit fericit,"],[8,"Ferice de cel ce locuiește cu o soție pricepută,"],[9,"Fericit cel ce a găsit prudența,"],[10,"Cât de mare este cel care a găsit înțelepciunea!"],[11,"Frica de Domnul întrece toate lucrurile."],[13,"Orice rană decât o rană a inimii!"],[14,"Orice calamitate, dar o calamitate de la cei care mă urăsc!"],[15,"Nu există venin mai rău decât veninul unui șarpe."],[16,"Prefer să locuiesc cu un leu și un dragon"],[17,"Răutatea unei femei își schimbă înfățișarea,"],[18,"Soțul ei va sta printre vecinii săi,"],[19,"Toată răutatea este mică în comparație cu răutatea unei femei."],[20,"Așa cum urcarea unui deal nisipos este pentru picioarele bătrânilor,"],[21,"Nu te lăsa prins de frumusețea unei femei."],[22,"Există mânie, obrăznicie și mare reproș"],[23,"O femeie rea este înjosirea inimii,"],[24,"Începutul păcatului a venit de la o femeie."],[25,"Nu da o priză apei,"],[26,"Dacă ea nu merge așa cum indicați,"]]],[26,[[1,"Fericit este soțul unei soții bune."],[2,"O soție credincioasă îi dă bucurie soțului ei."],[3,"O soție bună este un cadou grozav."],[4,"Fie că un om este bogat sau sărac,"],[5,"De trei lucruri i-a fost frică inimii mele,"],[6,"O durere a inimii și întristare este o femeie care este geloasă pe o altă femeie."],[7,"O femeie rea este ca un jug care se înfrânge."],[8,"O femeie beată provoacă o mare mânie."],[9,"Curvia unei femei este în ridicarea ochilor ei;"],[10,"Urmăriți cu strictețe o fiică încăpățânată,"],[11,"Ai grijă la un ochi obrăzător,"],[12,"Ea își va deschide gura ca un călător însetat,"],[13,"Harul unei soții îl va încânta pe soțul ei."],[14,"O femeie tăcută este un dar al Domnului."],[15,"O femeie modestă este har peste har."],[16,"Ca soarele când răsare în locurile cele mai înalte ale Domnului,"],[17,"Ca lampa care luminează pe sfeșnicul sfânt,"],[18,"Precum stâlpii de aur sunt pe o bază de argint,"],[28,"Pentru două lucruri inima mea este întristat,"],[29,"Este greu pentru un comerciant să se ferească de fapte greșite,"]]],[27,[[1,"Mulți au păcătuit pentru profit."],[2,"Așa cum un cui se va lipi rapid între îmbinările pietrelor,"],[3,"Dacă cineva nu se ține cu sârguință de frica de Domnul,"],[4,"În scuturarea unei situri, deșeurile rămân,"],[5,"Cuptorul testează vasele olarului;"],[6,"Fructul unui copac dezvăluie cultivarea lui,"],[7,"Nu lăudați pe nimeni înainte de a-i auzi gândurile,"],[8,"Dacă urmezi dreptatea, o vei dobândi,"],[9,"Păsările se vor întoarce la felul lor,"],[10,"Leul așteaptă pradă."],[11,"Discursul unui om evlavios este întotdeauna înțelept,"],[12,"Limitează-ți timpul printre oameni lipsiți de înțelegere,"],[13,"Vorbirea de proști este ofensatoare."],[14,"Vorbirea lor cu multe înjurături face părul să stea drept."],[15,"Lupta celor mândri duce la vărsare de sânge."],[16,"Cel care dezvăluie secrete distruge încrederea,"],[17,"Iubește un prieten și păstrează credința în el;"],[18,"căci precum un om și-a nimicit dușmanul,"],[19,"Ca o pasăre pe care ai eliberat-o din mâna ta,"],[20,"Nu-l urmări, căci a plecat departe,"],[21,"Căci o rană poate fi legată, iar după abuz poate fi împăcare;"],[22,"Cine face cu ochiul inventează lucruri rele;"],[23,"Când vei fi prezent, el va vorbi dulce,"],[24,"Am urât multe lucruri, dar nimic ca el."],[25,"Cine aruncă o piatră drept în sus, o aruncă pe capul său."],[26,"Cine sapă o groapă va cădea în ea."],[27,"Cine face lucruri rele, se vor întoarce asupra lui,"],[28,"Batjocura și ocara sunt de la aroganți."],[29,"Cei care se bucură de căderea celor evlavioși vor fi prinși într-o cursă."],[30,"Mânia și mânia, și acestea sunt urâciuni."]]],[28,[[1,"Cine se răzbună va găsi răzbunare de la Domnul,"],[2,"Iartă aproapelui tău răul pe care l-a făcut,"],[3,"Adăpostește cineva mânie împotriva altuia"],[4,"De un om ca el nu are milă,"],[5,"El însuși, fiind trup, hrănește mânia."],[6,"Amintește-ți ultimul tău sfârșit și oprește dușmănia."],[7,"Adu-ți aminte de porunci și nu te mânia pe aproapele tău."],[8,"Ferește-te de ceartă și îți vei diminua păcatele,"],[9,"Un om care este un păcătos va tulbura prietenii"],[10,"Cum este combustibilul focului, așa va arde;"],[11,"O ceartă începută în grabă aprinde un foc;"],[12,"Dacă suflați pe o scânteie, aceasta va arde;"],[13,"Blestema pe șoptător și cu limbă dublă,"],[14,"Un defăimător i-a zguduit pe mulți,"],[15,"Un defăimător a alungat femei curajoase"],[16,"Cine o ascultă nu va găsi odihnă,"],[17,"Lovitura de bici face un semn în carne,"],[18,"Mulți au căzut sub tăișul sabiei,"],[19,"Fericit este cel care este ferit de ea,"],[20,"Căci jugul lui este un jug de fier,"],[21,"Moartea lui este o moarte rea,"],[22,"Nu va avea stăpânire asupra oamenilor evlavioși."],[23,"Cei care părăsesc Domnul vor cădea în ea."],[24,"În timp ce îți îngrădești posesiunea cu spini,"],[25,"deci fă o balanță și o greutate pentru cuvintele tale,"],[26,"Ai grijă să nu aluneci cu ea,"]]],[29,[[1,"Cine are milă va împrumuta aproapelui său."],[2,"Împrumută aproapelui tău la vremea nevoii lui."],[3,"Întărește-ți cuvântul și păstrează credința în el;"],[4,"Mulți au considerat că un împrumut este o excepție,"],[5,"Până când va primi, va săruta mâinile unui bărbat."],[6,"Dacă va prevala, creditorul cu greu va primi jumătate;"],[7,"Mulți din cauza fraudei au refuzat."],[8,"Totuși, ai răbdare cu un bărbat în stare săracă."],[9,"Ajută un om sărac de dragul poruncii."],[10,"Pierde-ți banii pentru un frate și un prieten."],[11,"Alocă-ți comoara după poruncile Celui Prea Înalt"],[12,"Păstrați milostenia în camerele voastre"],[13,"Va lupta pentru tine împotriva inamicului tău"],[14,"Un om bun va fi garant pentru aproapele său."],[15,"Nu uitați de bunătatea garantului dvs.,"],[16,"Un păcătos va risipi proprietatea garantului său."],[17,"Cel care este nerecunoscător îl va dezamăgi pe cel care l-a eliberat."],[18,"A fi garant i-a destrămat pe mulți care prosperau"],[19,"Un păcătos care cade în garanție și își asumă contracte de muncă"],[20,"Ajută-ți aproapele după puterea ta,"],[21,"Elementele esențiale ale vieții sunt apa, pâinea,"],[22,"Mai bună este viața unui om sărac sub un adăpost de bușteni"],[23,"Cu puțin sau cu mult, fii bine mulțumit."],[24,"Este o viață mizerabilă să mergi din casă în casă."],[25,"Vei distra, vei servi băuturi și nu vei mulțumi."],[26,"„Vino aici, străine, pune o masă,"],[27,"— Pleacă, străin, căci un oaspete onorat este aici."],[28,"Aceste lucruri sunt dure pentru un om priceput:"]]],[30,[[1,"Cel care își iubește fiul va continua să-l pună bătăi,"],[2,"Cel ce-și pedepsește fiul va avea profit din el,"],[3,"Cel ce-și învață fiul își va provoca gelozia pe vrăjmașul său."],[4,"Tatăl său moare și este ca și cum n-ar fi murit;"],[5,"În viața lui, și-a văzut fiul și s-a bucurat."],[6,"A lăsat în urma lui un răzbunător împotriva dușmanilor săi,"],[7,"Cine face prea mult din fiul său își va lega rănile."],[8,"Un cal neîntrerupt devine încăpățânat."],[9,"Răsfățați-vă copilul și el vă va face să vă fie frică."],[10,"Nu râde cu el, ca nu cumva să fii întristat cu el,"],[11,"Nu-i da libertate în tinerețe,"],[12,"Pleacă-i gâtul în tinerețe,"],[13,"Pedepsește-ți fiul și dă-i de lucru,"],[14,"Mai bine este un om sărac, sănătos și în formă,"],[15,"Sănătatea și fitness-ul sunt mai bune decât tot aurul,"],[16,"Nu există bogăție mai bună decât sănătatea corpului."],[17,"Moartea este mai bună decât o viață amară,"],[18,"Lucruri bune s-au revărsat pe o gură închisă"],[19,"Ce folosește o ofrandă unui idol?"],[20,"văzând cu ochii și gemând,"],[21,"Nu da sufletul tau intristarii."],[22,"Bucuria inimii este viața unui om."],[23,"Iubește-ți propriul suflet și mângâie-ți inima."],[24,"Invidia și mânia scurtează viața."],[25,"Cei care sunt veseli și veseli"]]],[31,[[1,"Veghea care vine din bogății consumă carnea,"],[2,"Anxietatea de veghe va tânji la somn."],[3,"Un om bogat se chinuie să strângă bani împreună."],[4,"Un om sărac se chinuie din lipsă de substanță."],[5,"Cine iubește aurul nu va fi îndreptățit."],[6,"Mulți au fost dați ruinei de dragul aurului."],[7,"Este o piatră de poticnire pentru cei care se sacrifică pentru ea."],[8,"Binecuvântat este cel bogat care este găsit fără vină,"],[9,"Cine este el, ca să-l numim fericit?"],[10,"Cine a fost încercat de el și a fost găsit perfect?"],[11,"Prosperitatea lui va fi asigurată."],[12,"Stai la o masă grozavă? Nu fi lacom acolo."],[13,"Amintiți-vă că un ochi lacom este un lucru rău."],[14,"Nu întinde mâna oriunde arată."],[15,"Luați în considerare sentimentele aproapelui dvs. de unul singur."],[16,"Mănâncă ca o ființă umană acele lucruri care îți sunt puse înainte."],[17,"Fii primul care se oprește de dragul bunelor maniere."],[18,"Și dacă stai printre mulți,"],[19,"Cât de suficient pentru un om bine manierat este foarte puțin."],[20,"Somnul sănătos vine din alimentația moderată."],[21,"Și dacă ai fost forțat să mănânci,"],[22,"Ascultă-mă, fiule, și nu mă disprețui,"],[23,"Oamenii îl binecuvântează pe cel care este liberal cu mâncarea lui."],[24,"Orașul va murmura asupra celui care este zgârcit cu mâncarea lui."],[25,"Nu te arăta viteaz în vin,"],[26,"Cuptorul testează temperarea oțelului prin scufundare;"],[27,"Vinul este la fel de bun ca viața pentru oameni,"],[28,"Vin băut în sezon și cu moderație"],[29,"Vinul băut în exces este amărăciune sufletească,"],[30,"Beția sporește furia unui prost spre răul lui."],[31,"Nu-ți mustra aproapele la un banchet cu vin."]]],[32,[[1,"Te-au făcut conducătorul unei sărbători?"],[2,"Și când ți-ai îndeplinit toate îndatoririle, ia-ți locul,"],[3,"Vorbește, cei mai în vârstă, căci este dreptul tău, dar cu cunoștințe temeinice;"],[4,"Nu vărsați discuții acolo unde există o muzică."],[5,"Ca un sigiliu de rubin într-un decor de aur,"],[6,"Ca un sigiliu de smarald într-o lucrare de aur,"],[7,"Vorbește, tinere, dacă ești obligat,"],[8,"Rezumați-vă discursul, multe lucruri în câteva cuvinte."],[9,"Când sunteți printre oameni mari, nu vă comportați ca egalul lor."],[10,"Vitezele fulgerului înainte de tunet."],[11,"Ridică-te la timp și nu fi ultimul."],[12,"Distrează-te acolo și fă ceea ce este în inima ta."],[13,"Pentru aceste lucruri binecuvântează pe Făcătorul tău,"],[14,"Cine se teme de Domnul va primi disciplina."],[15,"Cine caută legea va fi plin de ea,"],[16,"Cei care se tem de Domnul vor găsi judecata adevărată,"],[17,"Un om păcătos evită mustrarea,"],[18,"O persoană sensibilă nu va neglija niciun gând."],[19,"Nu face nimic fără sfat,"],[20,"Nu intra într-o cale de conflict."],[21,"Nu fi prea încrezător pe un drum lin."],[22,"Feriți-vă de proprii copii."],[23,"În fiecare lucrare păzește-ți propriul suflet,"],[24,"Cine crede în lege ia seama de poruncă."]]],[33,[[1,"Niciun rău nu se va întâmpla celui ce se teme de Domnul,"],[2,"Un om înțelept nu va urî legea,"],[3,"Un om priceput își va pune încrederea în lege."],[4,"Pregătește-ți discursul și astfel vei fi auzit."],[5,"Inima unui prost este ca o roată de căruță."],[6,"Un cal armăsar este ca un prieten batjocoritor."],[7,"De ce o zi excelează pe alta,"],[8,"Ei se distingeau prin cunoștința Domnului,"],[9,"Pe unii dintre ei i-a înălțat și i-a sfințit,"],[10,"Și toți oamenii sunt de la pământ."],[11,"Prin abundența cunoștințelor Lui, Domnul i-a distins,"],[12,"Pe unii dintre ei i-a binecuvântat și înălțat,"],[13,"Ca lutul olarului în mâna lui,"],[14,"Binele este opusul răului,"],[15,"Privește astfel toate lucrările Celui Prea Înalt,"],[16,"Am fost ultimul de pază,"],[17,"Prin binecuvântarea Domnului am ajuns înaintea lor,"],[18,"Gândiți-vă că nu am muncit numai pentru mine,"],[19,"Ascultă-mă, voi mari oameni ai poporului,"],[20,"Fiului și soției, fratelui și prietenului,"],[21,"În timp ce încă trăiești și respirația este în tine,"],[22,"Căci este mai bine ca copiii tăi să ceară de la tine"],[23,"Excelează în toate lucrările tale."],[24,"În ziua în care vei pune capăt zilelor vieții tale,"],[25,"Furajele, un băț și poverile sunt pentru un măgar."],[26,"Pune-ți sclavul la muncă și vei găsi odihnă."],[27,"Jugul și biciul vor pleca gâtul."],[28,"Trimite-l la trudă, ca să nu fie leneș,"],[29,"Pune-l la muncă, așa cum este potrivit pentru el."],[30,"Nu fi excesiv față de niciunul."],[31,"Dacă ai un sclav, tratează-l ca pe tine însuți,"],[32,"Dacă ai un sclav, tratează-l ca pe tine însuți."],[33,"pe ce drum vei merge să-l cauți?"]]],[34,[[1,"Speranțele zadarnice și false sunt pentru un om lipsit de înțelegere."],[2,"Ca unul care prinde o umbră și urmărește vântul,"],[3,"Viziunea viselor este o reflectare,"],[4,"Din un lucru necurat ce se poate curăța?"],[5,"Divinațiile, ghiciturile și visele sunt zadarnice."],[6,"Dacă nu sunt trimiși într-o pedeapsă de la Cel Preaînalt,"],[7,"Căci visele au dus pe mulți în rătăcire."],[8,"Fără să minți legea se va împlini."],[9,"Un om bine instruit știe multe lucruri."],[10,"Cine nu are experiență știe puține lucruri."],[11,"Am văzut multe lucruri în călătoriile mele."],[12,"Am fost adesea în pericol chiar și de moarte."],[13,"Duhul celor ce se tem de Domnul va trăi,"],[14,"Cine se teme de Domnul nu se va teme și nu va fi laș,"],[15,"Binecuvântat este sufletul celui ce se teme de Domnul."],[16,"Ochii Domnului sunt asupra celor ce-L iubesc,"],[17,"El ridică sufletul și luminează ochii."],[18,"Cine jertfește un lucru primit pe nedrept, jertfa lui este făcută în batjocură."],[19,"Cel Preaînalt nu-i plăcea darurile celor nelegiuiți,"],[20,"Ca cel care ucide un fiu sub ochii tatălui său"],[21,"Pâinea celor nevoiași este viața săracilor."],[22,"Precum cel care-și ucide aproapele este cel care își ia existența."],[23,"Când unul construiește, iar altul trage în jos,"],[24,"Când unul se roagă, iar altul blestemă,"],[25,"Cel care se spală după ce a atins un cadavru și îl atinge din nou,"],[26,"Chiar și așa un om postește pentru păcatele sale,"]]],[35,[[1,"Cel ce păzește legea înmulțește darurile."],[2,"Cine întoarce o bunătate oferă făină fină."],[3,"Să te îndepărtezi de răutate este plăcut Domnului."],[4,"Vezi să nu arăți în prezența Domnului gol."],[5,"Căci toate aceste lucruri se fac din pricina poruncii."],[6,"Jertfa celor drepți îmbogățește altarul."],[7,"Jertfa unui om drept este acceptabilă."],[8,"Slăviți pe Domnul cu generozitate."],[9,"În fiecare dar arată o înfățișare veselă,"],[10,"Dă Celui Preaînalt după cum a dat El."],[11,"Căci Domnul răsplătește,"],[12,"Nu plănuiți să-l mituiți cu daruri, căci nu le va primi."],[13,"Nu va accepta nicio persoană împotriva unui om sărac."],[14,"El nu va disprețui în niciun fel cererea orfanului"],[15,"Nu curg lacrimile văduvei pe obraz?"],[16,"Cel care slujește lui Dumnezeu după bunăvoința lui va fi primit."],[17,"Rugăciunea celor smeriți străpunge norii."],[18,"Și Domnul nu va fi leneș și nici nu va avea răbdare față de ei,"],[19,"până când va plăti fiecăruia după faptele lui,"],[20,"Îndurarea este la fel de binevenită în timpul suferinței sale,"]]],[36,[[1,"Miluiește-ne pe noi, Doamne, Dumnezeul tuturor, și privește la noi cu har;"],[2,"și trimite frica ta asupra tuturor neamurilor."],[3,"Ridică-ți mâna împotriva națiunilor străine"],[4,"După cum ți-ai arătat sfințenia în noi înaintea lor,"],[5,"Să te cunoască, așa cum te-am cunoscut și noi,"],[6,"Arată semne noi și fă diferite minuni."],[7,"Ridică indignare și revarsă mânie."],[8,"Grăbește timpul și amintește-ți jurământul."],[9,"Cel ce scapă să fie mistuit de focul aprins."],[10,"Zdrobește capetele conducătorilor inamicilor"],[11,"Adună toate triburile lui Iacov laolaltă,"],[12,"Doamne, ai milă de poporul care este chemat pe numele Tău,"],[13,"Ai milă de cetatea sanctuarului tău,"],[14,"Umple Sionul. Înălțăți-vă oracolele"],[15,"Dă mărturie celor care au fost făpturile tale la început,"],[16,"Recompensează-i pe cei care te așteaptă,"],[17,"Ascultă, Doamne, rugăciunea robilor Tăi,"],[18,"Burta va mânca orice mâncare,"],[19,"Gura gustă carnea luată la vânătoare,"],[20,"O inimă contrară va provoca greutate."],[21,"O femeie va primi orice bărbat,"],[22,"Frumusețea unei femei înveselește chipul."],[23,"Dacă bunătatea și smerenia sunt pe limba ei,"],[24,"Cel care își are o soție obține cea mai bogată comoară,"],[25,"Acolo unde nu există gard viu, proprietatea va fi jefuită."],[26,"Căci cine ar avea încredere într-un tâlhar agil care sare din oraș în oraș?"]]],[37,[[1,"Fiecare prieten va spune: „Și eu sunt prietenul lui”;"],[2,"Nu există o durere până la moarte"],[3,"O, imaginație rea, de ce ai fost format?"],[4,"Există un tovarăș care se bucură de bucuria unui prieten,"],[5,"Există un tovarăș care de dragul burtei lucrează cu prietenul său,"],[6,"Nu uita un prieten din sufletul tău."],[7,"Fiecare consilier laudă sfatul,"],[8,"Lasă-ți sufletul să se ferească de un consilier,"],[9,"și să-ți spun: „Bună este calea ta”."],[10,"Nu te sfătui cu cineva care se uită cu degete la tine."],[11,"Nu te sfătui cu o femeie despre rivalul ei,"],[12,"Ci mai degrabă fii mereu cu un om evlavios,"],[13,"Asigură-ți sfatul inimii,"],[14,"Căci sufletul unui om este uneori înclinat să-l informeze"],[15,"Mai presus de toate acestea întreabă-l pe Cel Prea Înalt"],[16,"Lasă rațiunea să fie începutul oricărei lucrări."],[17,"Ca semn al schimbării inimii,"],[18,"se ridică patru feluri de lucruri:"],[19,"Există unul care este deștept și instructorul multora,"],[20,"Există unul care este subtil în cuvinte și este urât."],[21,"Căci harul nu i-a fost dat de la Domnul,"],[22,"Există unul care este înțelept cu propriul său suflet;"],[23,"Un om înțelept își va instrui propriul popor."],[24,"Un om înțelept va fi plin de binecuvântare."],[25,"Viața unui om se numără pe zile."],[26,"Omul înțelept va moșteni încredere în poporul său."],[27,"Fiul meu, testează-ți sufletul în viața ta."],[28,"Căci nu toate lucrurile sunt de folos tuturor oamenilor."],[29,"Nu fi nesățios în nici un lux."],[30,"Căci supraalimentarea aduce boală,"],[31,"Din cauza lăcomiei, mulți au pierit,"]]],[38,[[1,"Onorează un medic după nevoia ta cu onorurile care i se cuvine,"],[2,"Căci vindecarea vine de la Cel Prea Înalt,"],[3,"Îndemânarea medicului îi va ridica capul."],[4,"Domnul a creat medicamente din pământ."],[5,"Apa nu a fost dulce cu lemne,"],[6,"Le-a dat bărbaților pricepere"],[7,"Cu ei vindecă"],[8,"Cu acestea, farmacistul face un amestec."],[9,"Fiul meu, în boala ta nu fi neglijent,"],[10,"Îndepărtează faptele rele și îndreaptă-ți mâinile în dreptate."],[11,"Dă o mireasmă dulce și un amintire de făină fină,"],[12,"Atunci dă locul medicului, căci cu adevărat Domnul l-a creat."],[13,"Există o perioadă în care recuperarea este în mâinile lor."],[14,"Căci și ei vor întreba pe Domnul"],[15,"Cel ce păcătuiește înaintea Făcătorului Său,"],[16,"Fiul meu, lasă-ți lacrimile să cadă peste morți,"],[17,"Fă plâns amar și plânge pătimaș."],[18,"Căci din întristare vine moartea."],[19,"În calamitate, rămâne și tristețea."],[20,"Nu da inima ta intristarii."],[21,"Nu uita, căci nu mai există întoarcere."],[22,"Adu-ți aminte de sfârșitul Lui, căci așa va fi și al tău:"],[23,"Când mortul se odihnește, lăsați-i pomenirea să se odihnească."],[24,"Înțelepciunea scribului vine cu ocazia petrecerii timpului liber."],[25,"Cum ar putea deveni înțelept cel care ține plugul,"],[26,"Își va pune inima să-și întoarcă brazdele."],[27,"La fel este și fiecare meșter și meșter artizan"],[28,"La fel este și fierarul care stă lângă nicovală"],[29,"La fel și olarul care stă la lucru"],[30,"El va modela lutul cu brațul său"],[31,"Toate acestea și-au pus încrederea în mâinile lor."],[32,"Fără acestea nici un oraș nu ar fi locuit."],[33,"Ei nu vor fi căutați în consiliul poporului."],[34,"Dar ei vor menține țesătura epocii."]]],[39,[[1,"Nu așa și cel care și-a aplicat sufletul"],[2,"El va păzi cuvintele oamenilor de renume"],[3,"El va căuta sensul ascuns al proverbelor"],[4,"El va sluji printre oameni mari"],[5,"El își va pune inima să se întoarcă devreme la Domnul care l-a făcut,"],[6,"Dacă marele Domn vrea,"],[7,"El își va îndruma sfatul și cunoștințele,"],[8,"El va arăta instrucțiunile pe care i-au fost învățate"],[9,"Mulți îi vor lăuda înțelegerea."],[10,"Națiunile își vor declara înțelepciunea."],[11,"Dacă va continua, va lăsa un nume mai mare decât o mie."],[12,"Încă voi rosti mai multe, la care m-am gândit."],[13,"Ascultați-mă, copii sfinți,"],[14,"Oferă un parfum dulce precum tămâia."],[15,"Mărește-i numele"],[16,"Toate lucrările Domnului sunt foarte bune,"],[17,"Nimeni nu poate spune: „Ce este asta?” \"De ce este asta?\""],[18,"La porunca lui se împlinește toată plăcerea lui."],[19,"Lucrările oricărei făpturi sunt înaintea lui."],[20,"El vede din veșnicie în veșnicie."],[21,"Nimeni nu poate spune: „Ce este asta?” \"De ce este asta?\""],[22,"Binecuvântarea Lui a acoperit uscatul ca un râu"],[23,"După cum a sărat apele,"],[24,"Căile Lui sunt clare pentru cele sfinte."],[25,"Lucrurile bune sunt create de la început pentru bine."],[26,"Principalele lucruri necesare vieții omului"],[27,"Toate aceste lucruri sunt spre binele celor evlavioși,"],[28,"Sunt vânturi care sunt create pentru răzbunare,"],[29,"Foc, grindină, foamete și moarte -"],[30,"dinți de fiare sălbatice, scorpioni, viperă,"],[31,"Ei se vor bucura de porunca Lui,"],[32,"Prin urmare, de la început am fost convins,"],[33,"Toate lucrările Domnului sunt bune."],[34,"Nimeni nu poate spune: „Acesta este mai rău decât atât”"],[35,"Acum, cu toate inimile și vocile voastre, cântați laude"]]],[40,[[1,"O mare muncă este creată pentru fiecare om."],[2,"Așteptarea lucrurilor care vor veni și ziua morții,"],[3,"De la Cel ce șade pe un tron ​​al slavei,"],[4,"de la cel ce poartă purpuriu și coroană,"],[5,"există mânie, gelozie, necaz, neliniște,"],[6,"Se odihnește puțin sau deloc,"],[7,"Chiar în timpul eliberării sale, el se trezește,"],[8,"Pentru toate creaturile, umane și animale,"],[9,"vino moarte, vărsare de sânge, ceartă, sabie,"],[10,"Toate aceste lucruri au fost create pentru cei răi,"],[11,"Toate lucrurile care sunt de pe pământ se întorc din nou către pământ."],[12,"Toate mituirea și nedreptatea vor fi șterse."],[13,"Bunurile celor nedrepți vor fi secate ca un râu,"],[14,"Deschizându-și mâinile, omul se va bucura;"],[15,"Copiii celor nelegiuiți nu vor crește multe ramuri,"],[16,"Stufurile de lângă fiecare mal de apă sau râu"],[17,"Bunătatea este ca o grădină de binecuvântări."],[18,"Viața celui care muncește și este mulțumit va fi dulce."],[19,"Copiii și construirea unui oraș stabilesc un nume."],[20,"Vinul și muzica bucură inima."],[21,"Pipa și lăuta fac o melodie plăcută."],[22,"Ochiul tău dorește har și frumusețe,"],[23,"Un prieten și un însoțitor sunt întotdeauna bineveniți,"],[24,"Rudele și ajutoarele sunt pentru un timp de suferință,"],[25,"Aurul și argintul vor face piciorul să stea sigur,"],[26,"Bogăția și puterea vor ridica inima."],[27,"Frica de Domnul este ca o grădină de binecuvântare"],[28,"Fiul meu, nu duce viața de cerșetor."],[29,"Un om care se uită la masa altuia,"],[30,"Cerșetoria va fi dulce în gura celor fără rușine,"]]],[41,[[1,"O, moarte, cât de amară este amintirea ta pentru un om care este în pace în averea lui,"],[2,"O, moarte, sentința ta este plăcută unui om care este nevoit și care nu are putere,"],[3,"Nu-ți fie frică de condamnarea la moarte."],[4,"Și de ce refuzi când este plăcerea Celui Prea Înalt?"],[5,"Copiii păcătoșilor sunt copii abominabili"],[6,"Moștenirea copiilor păcătoșilor va pieri"],[7,"Copiii se vor plânge de un tată nelegiuit,"],[8,"Vai de voi, oameni nelegiuiți,"],[9,"Dacă te naști, te vei naște pentru un blestem."],[10,"Toate lucrurile care sunt de pe pământ se vor întoarce pe pământ;"],[11,"Jeliul oamenilor este legat de trupurile lor;"],[12,"Ai grijă de numele tău,"],[13,"O viață bună are numărul ei de zile,"],[14,"Copii mei, urmați instrucțiunile în pace."],[15,"Mai bine este un om care își ascunde prostia"],[16,"Prin urmare, arătați respect pentru cuvintele mele;"],[17,"Să vă fie rușine de imoralitate sexuală înaintea tatălui și a mamei,"],[18,"a unei infracțiuni în fața unui judecător și conducător,"],[19,"şi de furt în locul unde locuiţi."],[20,"de tăcere înaintea celor care te salută,"],[21,"de a-ți întoarce fața de la o rudă,"],[22,"de a se amesteca cu servitoarea lui - și nu te apropia de patul ei,"],[23,"de a repeta și a vorbi ceea ce ai auzit,"],[24,"Deci îți va fi rușine de lucrurile potrivite"]]],[42,[[1,"Nu-ți fie rușine de aceste lucruri,"],[2,"a legii Celui Prea Înalt și a legământului său,"],[3,"de socoteală cu un partener și cu călătorii,"],[4,"de exactitatea cântarelor și greutăților,"],[5,"de negocieri cu comercianții,"],[6,"Un sigiliu este bun acolo unde este o soție rea."],[7,"Orice ai preda, lasă-l după număr și greutate."],[8,"Nu-ți fie rușine să-i instruiești pe cei neînțelepți și proști,"],[9,"O fiică este o cauză secretă de veghe pentru un tată."],[10,"în fecioria ei, ca să nu se pângărească și să fie însărcinată în casa tatălui ei;"],[11,"Țineți o supraveghere strictă asupra unei fiice încăpățânate,"],[12,"Nu te uita la fiecare corp frumos."],[13,"Căci din haine vine o molie,"],[14,"Mai bună este răutatea unui bărbat decât a unei femei plăcute,"],[15,"Voi aminti acum de lucrările Domnului,"],[16,"Soarele care dă lumină se uită la toate lucrurile."],[17,"Domnul nu a dat putere sfinților să vestească toate lucrările Sale minunate,"],[18,"El caută adâncul și inima."],[19,"El declară lucrurile trecute și cele ce vor fi,"],[20,"Niciun gând nu-i scapă."],[21,"El a poruncit lucrările mărețe ale înțelepciunii sale."],[22,"Cât de dorite sunt toate lucrările lui!"],[23,"Toate aceste lucruri trăiesc și rămân pentru totdeauna în tot felul de întrebuințări."],[24,"Toate lucrurile sunt în perechi, unul opus celuilalt."],[25,"Un lucru stabilește lucrurile bune ale altuia."]]],[43,[[1,"Mândria înălțimilor cerești este cerul senin,"],[2,"Soarele, când apare, aducând vești când răsare,"],[3,"La amiază, seacă pământul."],[4,"Un om care îngrijește un cuptor este în căldură arzătoare,"],[5,"Mare este Domnul care a făcut-o."],[6,"Luna marchează schimbarea anotimpurilor,"],[7,"De la lună este semnul zilelor de sărbătoare,"],[8,"Luna este numită după numele ei,"],[9,"frumusețea cerului, slava stelelor,"],[10,"La cuvântul Sfântului, ei vor sta în ordinea cuvenită."],[11,"Privește curcubeul și lăudați pe cel care l-a făcut."],[12,"Înconjoară cerul cu cercul său glorios."],[13,"Prin porunca lui, el face să cadă zăpada"],[14,"Prin urmare, depozitele sunt deschise,"],[15,"Prin puterea sa puternică, el întărește norii"],[16,"La apariția lui, munții vor fi zdruncinați."],[17,"Glasul tunetului lui mustră pământul."],[18,"Ochiul este uluit de frumusețea albului său."],[19,"El varsă și ger pe pământ ca sarea."],[20,"Bate vântul rece de nord"],[21,"Va mistui munții, va arde pustia,"],[22,"O ceață care vine repede vindecă toate lucrurile."],[23,"Prin sfatul său, el a calmat adâncul"],[24,"Cei care navighează pe mare povestesc despre pericolele ei."],[25,"Există și acele lucrări ciudate și minunate în ea -"],[26,"Din cauza lui, mesagerii lui reușesc."],[27,"S-ar putea să spunem multe lucruri, dar nu am putea spune destule."],[28,"Cum am putea să avem putere să-l slăvim?"],[29,"Domnul este minunat și extraordinar de mare!"],[30,"Slăviți pe Domnul și înălțați-l cât puteți!"],[31,"Cine l-a văzut, ca să-l descrie?"],[32,"Multe lucruri mai mari decât acestea sunt ascunse,"],[33,"Căci Domnul a făcut toate lucrurile."]]],[44,[[1,"Să lăudăm acum bărbații celebri,"],[2,"Domnul a creat în ei mare slavă -"],[3,"Unii au domnit în regatele lor"],[4,"conducătorii poporului prin sfaturile lor,"],[5,"Unele au compus melodii muzicale,"],[6,"oameni bogați înzestrați cu abilități,"],[7,"Toate acestea au fost onorate în generațiile lor,"],[8,"Unii dintre ei au lăsat un nume în urma lor,"],[9,"Dar despre alții, nu există amintire."],[10,"Dar aceștia erau oameni ai milei,"],[11,"O moștenire bună rămâne cu urmașii lor."],[12,"Odraslele lor stau neclintite,"],[13,"Progenitul lor va rămâne pentru totdeauna."],[14,"Trupurile lor au fost îngropate în pace."],[15,"Oamenii își vor declara înțelepciunea."],[16,"Enoh a plăcut Domnului și a fost înălțat,"],[17,"Noe a fost găsit perfect și drept."],[18,"Legăminte veșnice au fost făcute cu el,"],[19,"Avraam a fost un mare tată al unei mulțimi de națiuni."],[20,"care a păzit legea Celui Prea Înalt,"],[21,"De aceea l-a asigurat printr-un jurământ"],[22,"Și în Isaac, el a stabilit aceeași asigurare pentru Avraam, tatăl său,"],[23,"El a pus-o să se odihnească pe capul lui Iacov."]]],[45,[[1,"El a scos din el un om milostiv,"],[2,"L-a făcut egal cu slava sfinților,"],[3,"Prin cuvintele sale, el a făcut să înceteze minunile."],[4,"El l-a sfințit în credincioșia și blândețea lui."],[5,"L-a făcut să-i audă vocea,"],[6,"El l-a înălțat pe Aaron, un om sfânt ca Moise,"],[7,"El a stabilit un legământ veșnic cu el,"],[8,"L-a îmbrăcat în splendoare desăvârșită,"],[9,"L-a înconjurat cu rodii;"],[10,"cu o haină sfântă, cu aur, albastru și purpuriu, lucrare de broderie;"],[11,"cu stacojiu răsucit, lucrarea meșterului;"],[12,"cu o coroană de aur pe mitra, având gravat pe ea, ca pe un sigiliu, „SFIȚINȚE”,"],[13,"Înainte de el nu a existat niciodată așa ceva."],[14,"Jertfele Lui vor fi arse în întregime,"],[15,"Moise l-a sfințit,"],[16,"El l-a ales dintre toate vii"],[17,"El i-a dat în poruncile lui,"],[18,"Străinii au conspirat împotriva lui"],[19,"Domnul a văzut-o și i-a fost neplăcut."],[20,"El a adăugat glorie lui Aaron,"],[21,"Căci ei mănâncă jertfele Domnului,"],[22,"Totuși, în țara poporului, el nu are moștenire,"],[23,"Fineas, fiul lui Eleazar, este al treilea în slavă,"],[24,"De aceea, a fost stabilit pentru el un legământ de pace,"],[25,"De asemenea, a făcut un legământ cu David, fiul lui Isai, din seminția lui Iuda."],[26,"Dumnezeu să-ți dea înțelepciune în inima ta"]]],[46,[[1,"Iosua, fiul lui Nun, a fost viteaz în război,"],[2,"Cum a fost glorificat în ridicarea mâinilor,"],[3,"Cine înaintea lui a stat atât de ferm?"],[4,"Nu s-a întors soarele de mâna lui?"],[5,"A chemat pe Cel Preaînalt, pe Cel Puternic,"],[6,"Cu grindină de o mare putere,"],[7,"De asemenea, pe vremea lui Moise, el a făcut o lucrare de îndurare -"],[8,"Și din șase sute de mii de oameni pe jos, numai ei doi s-au păstrat"],[9,"Domnul i-a dat putere lui Caleb,"],[10,"pentru ca toți copiii lui Israel să vadă că este bine să-L urmezi pe Domnul."],[11,"De asemenea, judecătorii, fiecare după numele lui,"],[12,"Fie ca oasele lor să înflorească din nou din locul lor."],[13,"Samuel, profetul Domnului, iubit de Domnul său,"],[14,"După legea Domnului, a judecat adunarea,"],[15,"Prin credincioșia sa, s-a dovedit că este un profet."],[16,"Când dușmanii lui l-au apăsat din toate părțile,"],[17,"Atunci Domnul a tunat din cer."],[18,"El i-a distrus cu totul pe conducătorii tirienilor"],[19,"Înainte de timpul somnului său veac,"],[20,"Chiar și după ce a adormit, a profețit:"]]],[47,[[1,"După el, Nathan se ridică"],[2,"Ca și grăsimea când este separată de jertfa de pace,"],[3,"S-a jucat cu leii ca și cu copiii,"],[4,"În tinerețe nu a ucis un uriaș,"],[5,"Căci a chemat pe Domnul Preaînalt,"],[6,"Așa că l-au glorificat pentru zecile lui de mii,"],[7,"Căci a nimicit pe vrăjmașii din toate părțile,"],[8,"În fiecare lucrare a lui, a mulțumit Sfântului Preaînalt cu cuvinte de slavă."],[9,"El a pus cântăreți înaintea altarului,"],[10,"El a dat frumusețe sărbătorilor,"],[11,"Domnul i-a luat păcatele,"],[12,"După el s-a ridicat un fiu înțelept,"],[13,"Solomon a domnit în zile de pace."],[14,"Cât de înțelept ai fost făcut în tinerețe,"],[15,"Influența ta a acoperit pământul,"],[16,"Numele tău a ajuns până în insulele îndepărtate,"],[17,"Pentru cântecele tale, proverbe, pilde,"],[18,"Pe numele Domnului Dumnezeu,"],[19,"Ți-ai plecat coapsele în fața femeilor,"],[20,"Ți-ai stricat onoarea,"],[21,"pentru că suveranitatea a fost împărțită,"],[22,"Dar Domnul nu va părăsi niciodată mila Lui."],[23,"Aşa că Solomon s-a odihnit cu părinţii săi."],[24,"Păcatele lor s-au înmulțit extrem de mult,"],[25,"Căci ei căutau orice fel de răutate,"]]],[48,[[1,"Atunci s-a ridicat Ilie, profetul ca focul."],[2,"El a adus peste ei foamete,"],[3,"Prin cuvântul Domnului a închis cerurile."],[4,"Cât de slăvit ai fost, Ilie, în faptele tale minunate!"],[5,"Ai înviat un mort din moarte,"],[6,"Ai doborât regii la nimicire,"],[7,"Ai auzit mustrare în Sinai,"],[8,"Ai uns regi pentru pedeapsa,"],[9,"Ai fost luat într-o furtună de foc,"],[10,"Ai fost înregistrat pentru mustrări în anotimpurile lor,"],[11,"Fericiți cei care te-au văzut,"],[12,"Ilie era învăluit într-un vârtej."],[13,"Nimic nu era prea greu pentru el."],[14,"Ca și în viața lui, a făcut minuni,"],[15,"Pentru toate acestea, oamenii nu s-au pocăit."],[16,"Unii dintre ei au făcut ceea ce era corect,"],[17,"Ezechia și-a întărit orașul,"],[18,"În zilele lui Sanherib a invadat,"],[19,"Atunci inimile și mâinile lor s-au scuturat,"],[20,"Dar au chemat pe Domnul cel milostiv,"],[21,"El a lovit tabăra asirienilor,"],[22,"Căci Ezechia a făcut ceea ce este plăcut Domnului,"],[23,"În zilele lui, soarele s-a întors înapoi."],[24,"El a văzut printr-un spirit excelent ce avea să se întâmple în viitor;"],[25,"El a arătat lucrurile care se vor întâmpla până la sfârșitul timpului,"]]],[49,[[1,"Amintirea lui Iosia este asemenea compoziției de tămâie"],[2,"El a făcut ce era corect în reformarea poporului,"],[3,"Și-a îndreptat inima spre Domnul."],[4,"Cu excepția lui David, Ezechia și Iosia,"],[5,"Și-au dat puterea altora,"],[6,"Au dat foc orașului ales al sanctuarului"],[7,"Căci l-au maltratat;"],[8,"Ezechiel a văzut viziunea slavei,"],[9,"Căci cu adevărat și-a amintit de dușmani în furtuna de ploaie,"],[10,"De asemenea, dintre cei doisprezece profeți,"],[11,"Cum îl vom mări pe Zorobabel?"],[12,"Așa a fost Isus, fiul lui Iosedec,"],[13,"De asemenea, amintirea lui Neemia este mare."],[14,"Niciun om nu a fost creat pe pământ ca Enoh,"],[15,"Nici nu s-a născut un om ca Iosif,"],[16,"Sem și Set au fost onorați printre oameni,"]]],[50,[[1,"Era Simon, fiul lui Onia, marele preot,"],[2,"Fundația a fost construită de el până la înălțimea pereților dubli,"],[3,"Pe vremea lui, s-a săpat o cisterna de apă,"],[4,"El a plănuit să-și salveze poporul de la ruină,"],[5,"Cât de glorios era când oamenii s-au adunat în jurul lui"],[6,"Era ca steaua dimineții printre nori,"],[7,"ca soarele care strălucește peste templul Celui Prea Înalt,"],[8,"ca trandafirii în zilele primelor fructe,"],[9,"ca focul și tămâia în cădelniță,"],[10,"ca un măslin încărcat cu fructe,"],[11,"Când și-a îmbrăcat haina glorioasă,"],[12,"Când a primit porțiile din mâinile preoților,"],[13,"Toți fiii lui Aaron în slava lor,"],[14,"Terminând slujba la altare,"],[15,"și-a întins mâna spre paharul libației,"],[16,"Atunci fiii lui Aaron au strigat."],[17,"Apoi toți oamenii împreună s-au grăbit,"],[18,"Cântăreții l-au lăudat și cu glasul."],[19,"Și poporul L-a implorat pe Domnul Prea Înalt,"],[20,"Apoi a coborât și și-a ridicat mâinile"],[21,"S-a închinat a doua oară în închinare,"],[22,"Acum binecuvântați pe Dumnezeul tuturor,"],[23,"El să ne dea bucuria inimii,"],[24,"să ne încredințeze mila Lui,"],[25,"Cu două neamuri sufletul meu este supărat,"],[26,"Cei care stau pe muntele Samariei, filistenii,"],[27,"Am scris în această carte învățătura înțelegerii și cunoașterii,"],[28,"Ferice de cel care va exercita aceste lucruri."],[29,"Căci dacă le va face, va fi puternic în toate lucrurile,"]]],[51,[[1,"Îți voi mulțumi, Doamne, Împărate,"],[2,"căci tu ai fost ocrotitorul și ajutorul meu,"],[3,"și m-a scăpat, după belșugul milei Tale și al numelui tău,"],[4,"de la sufocarea unui foc din toate părțile,"],[5,"din adâncul pântecelui lui Hades,"],[6,"calomnia unei limbi nedrepte la adresa regelui."],[7,"M-au înconjurat din toate părțile."],[8,"Atunci mi-am adus aminte de mila Ta, Doamne,"],[9,"Mi-am ridicat rugăciunea de pe pământ,"],[10,"Am chemat pe Domnul, Tatăl Domnului meu,"],[11,"Îți voi lăuda numele neîncetat."],[12,"M-ai salvat de la distrugere"],[13,"Când eram încă tânăr,"],[14,"Înainte de templu am cerut-o."],[15,"De la prima floare până la strugure care se coace, inima mea s-a bucurat de ea."],[16,"Mi-am înclinat puțin urechea și am primit-o,"],[17,"Am profitat de ea."],[18,"Căci m-am hotărât să o exersez."],[19,"Sufletul meu s-a luptat cu ea."],[20,"Mi-am îndreptat sufletul spre ea."],[21,"Și burta mea era tulburată să o caut."],[22,"Domnul mi-a dat o limbă pentru răsplata mea."],[23,"Apropiați-vă de mine, toți cei needucați,"],[24,"De ce vă lipsesc toți aceste lucruri,"],[25,"Am deschis gura și am vorbit,"],[26,"Pune-ți gâtul sub jug,"],[27,"Vezi cu ochii tăi"],[28,"Primiți instrucțiuni cu o mare sumă de argint,"],[29,"Fie ca sufletul tău să se bucure de mila lui,"],[30,"Lucrează-ți munca înainte să vină timpul,"]]]];